#include <iostream>
#include <vector>
#include <utility>

// Display array elements using const reference (read-only)
void printArray(const std::vector<int>& arr) {
    for (size_t i = 0; i < arr.size(); ++i) {
        std::cout << (i == 0 ? "" : " ") << arr[i];
    }
    std::cout << "\n";
}

// Bubble sort modifying the original vector
void bubbleSort(std::vector<int>& arr) {
    size_t n = arr.size();
    for (size_t pass = 1; pass < n; ++pass) {
        for (size_t i = 0; i < n - 1; ++i) {
            if (arr[i] > arr[i + 1]) {
                // Swap elements using std::swap
                std::swap(arr[i], arr[i + 1]);
            }
        }
    }
}

int main() {
    std::vector<int> data = {2, 6, 4, 8, 10, 12, 89, 68, 45, 37};

    std::cout << "Original:";
    printArray(data);

    bubbleSort(data);

    std::cout << "Sorted:";
    printArray(data);

    return 0;
}

#include <iostream>
#include <iomanip>
#include <vector>

// Compute and display the arithmetic mean of survey data
void calculateMean(const std::vector<unsigned int>& answer) {
    unsigned int total = 0;
    for (size_t j = 0; j < answer.size(); ++j) {
        total += answer[j];
    }

    double avg = static_cast<double>(total) / static_cast<double>(answer.size());
    std::cout << "Total: " << total << "\n";
    std::cout << "Count: " << answer.size() << "\n";
    std::cout << std::fixed << std::setprecision(4);
    std::cout << "Mean: " << avg << "\n";
}

int main() {
    // A compact sample representative of the survey dataset
    std::vector<unsigned int> response = {
        6, 7, 8, 9, 8, 7, 8, 9, 8, 9,
        7, 8, 9, 5, 9, 8, 7, 8, 7, 8
    };

    calculateMean(response);
    return 0;
}
